  S.C.CAF = mkGroups("CAF", "CAF Champions League", "CAF Champions", Q.CAF, {ng: 4, double: true, mdW: [9, 12, 14, 17, 20, 22], koW: [[27, 29], [33, 35], [37, 39]], lvl: 7, conf: "CAF"});
