  if (!FEM && L.LIB >= 0 && L.SUD >= 0 && L.LIB !== L.SUD && L.LIB != null && L.SUD != null) S.C.REC = mkKO("REC", "Recopa Sudamericana", "Recopa", [{n: N_("Final"), W: [23, 24]}], [mkTie(L.SUD, L.LIB)], {lvl: 3, conf: "CONMEBOL"});
