  var c = mkGroups(T.k, T.n + " " + year, T.n, parts, {ng: T.groups, double: false, mdW: [41, 42, 43], nat: true, perGroup: 2, thirds: T.thirds, koW: koWeeksFrom(44, nR), lvl: tournamentLvl(T.k), conf: T.conf});
  c.tk = T.k; c.year = year;
