    p.tx.push({y: S.yr, w: S.w, from: old, to: o.club, fee: o.fee, loan: false});
    milestone(o.fee ? tr("Fichaje por el {club} ({fee})", {club: clubName(o.club), fee: fmtMoney(o.fee)}) : tr("Fichaje por el {club} (libre)", {club: clubName(o.club)}));
