  var main = Object.keys(clubs).sort(function (a, b) { return clubs[b] - clubs[a]; })[0];
  S.retired = {y: S.yr + 1, age: p.age, lg: lg, tot: tot, main: main != null ? +main : p.club};
  S.ph = "ret";
