  var ch = momPreview({goal: out.goal, concede: out.concede, save: out.save, red: out.red, yellow: out.yellow, rating: out.rating, fx: susp ? {susp: susp} : null});
  return ch.concat((fxCh || []).filter(function (c) { return !(susp && c[0] === "susp"); }));
