    if (res.n) chips.push(["note", 0, res.n]);
    S.p.evCd[ev.id] = S.yr;
    card = {t: "decision", tipo: ev.tipo, cat: ev.cat, title: title, choice: o.t, txt: res.txt, chips: chips, y: S.yr, good: res.sure ? null : !!res.good, pct: res.sure ? null : Math.round(res.p * 100)};
    S.pend.shift();
