      Y.cur = x;
      try { var ok = (!ev.still || ev.still(Y)) && (ev.manual || !ev.when || !!ev.when(Y)); if (ok) ok = !!ev.text(Y) && ev.opts(Y).length > 0; return ok; }
      catch (e) { return false; } finally { Y.cur = null; }
