function MEV(d) { i18nFields(d); MEVENTS.push(d); MEV_BY_ID[d.id] = d; }
function MMO(d) { i18nFields(d); MGR_MOMENTS.push(d); MGR_MOM_BY_ID[d.id] = d; }

/* contexto que ven las decisiones del entrenador */
