function tDesc(t) { return tr("{name} ({pos}, {age} años, media {ovr}, potencial {potMin}–{potMax}).", {name: t.fn + " " + t.ln, pos: lcT(posName(t.pos)), age: t.age, ovr: Math.round(t.ovr), potMin: t.potR[0], potMax: t.potR[1]}); }

