    var tk = {9: N_("Superar la fase de liga de {comp}"), 3: N_("Llegar a cuartos de {comp}"), 2: N_("Llegar a semifinales de {comp}"), 1: N_("Llegar a la final de {comp}"), 0: N_("Ganar {comp}")};
