  if (x.typ === "lp") return x.res.map(function (r) { return r[0]; });
  for (var j = 0; j < x.res.length; j++) { var t = x.res[j]; if (t[0] === x.me) return [t[1]]; if (t[1] === x.me) return [t[0]]; }
