    var sums = x.res.map(function (g) { var s = 0; g.forEach(function (t) { s += drawRt(c, t); }); return s / Math.max(1, g.length); });
    var gi = 0; x.res.forEach(function (g, i) { if (g.indexOf(me) >= 0) gi = i; });
