function mpNorm(s) { return String(s).toLowerCase().replace(/[áàä]/g, "a").replace(/[éèë]/g, "e").replace(/[íìï]/g, "i").replace(/[óòö]/g, "o").replace(/[úùü]/g, "u").replace(/ç/g, "c").replace(/ñ/g, "n").replace(/[^a-z0-9 ]/g, " ").replace(/\s+/g, " ").trim(); }
