  try { l = ni === cur ? [] : mpNatPool(ni).slice(0, 14); } catch (e) { l = []; }
  if (!l.length) { var pool = namePool(ni), lns = pool.l.split(","); for (var i = 0; i < 11; i++) l.push({ln: lns[hashStr("o" + ni + i) % lns.length], pos: i ? (i < 5 ? "DFC" : i < 8 ? "MC" : "DC") : "POR"}); }
  return l;
