  var rec = {y: S.yr, w: S.w, opp: o.opp, cmp: o.cmp, rn: o.rn || "", h: o.h, gu: o.gu, gt: o.gt, eu: o.eu || 0, ett: o.ett || 0, et: !!o.et, p: o.p || null};
  rec.ev = mpNatEvents(rec, sq.map(function (x) { return {ln: x.ln, pos: x.pos}; }), mpOppNames(o.opp));
