    var r = ptPlay(x, opt.mod), chips = mgrFx(opt.fx);
    if (r.pos === 1) { m.fans = clamp(m.fans + 2, 0, 100); m.chem = clamp(m.chem + 2, 0, 100); chips.push(["chem", 2]); }
    if (o.i === 1) mActive().forEach(function (p) { if (p.age <= 21) p.mor = clamp(p.mor + 4, 0, 100); });
    ptRecord(x, r, 0);
