    var wkNow = v === "create" && UI.cr ? (UI.cr.g === "f" ? "f2" : "m") : (v === "game" || v === "draft") && S ? worldKey(S) : null;
    if (wkNow && W.wk !== wkNow) { buildWorld(wkNow); if (S && worldKey(S) === wkNow && S.custom) applyCustom(); }
