    if (o.blind) return '<button class="opt" data-a="choose" data-i="' + i + '"><span class="ot"><b>' + h(o.t) + "</b></span>" + (o.ref ? '<span class="oref">' + h(o.ref) + "</span>" : "") + "</button>";
