    s += '<rect x="40" y="0" width="280" height="118" fill="url(#' + id + 'l)"/><rect x="38" y="0" width="2" height="118" fill="#000" opacity=".4"/><rect x="320" y="0" width="2" height="118" fill="#000" opacity=".4"/>';
    /* protagonista sentado */
