    if (dark(A) && COL_OK.test(ca[1])) A = ca[1];
    if (d(A, B) < 120 || dark(B)) B = COL_OK.test(cb[1]) && d(A, cb[1]) >= 120 ? cb[1] : d(A, "#edf1e8") > 200 ? "#edf1e8" : "#5f7477";
