    document.body.appendChild(el);
    el.addEventListener("keydown", function (e) { if (e.key === "Escape") { e.preventDefault(); if (D && D.done) close(); else skip(); } });
    var f = el.querySelector(".drw-spd button"); if (f) f.focus({preventScroll: true});
