    var opt = function (lab, ks) { return ks.length ? '<optgroup label="' + h(lab) + '">' + ks.map(function (k) { return '<option value="' + h(k) + '"' + (k === ui.cupSel ? " selected" : "") + ">" + h(trComp(S.C[k].n)) + "</option>"; }).join("") + "</optgroup>" : ""; };
